import{c as r,Q as e,j as a,m as o}from"./chunks/framework.rWdQudnF.js";const g=JSON.parse('{"title":"架构师-备考 综合知识-软件工程-设计模式","description":"","frontmatter":{"title":"架构师-备考 综合知识-软件工程-设计模式"},"headers":[],"relativePath":"综合知识/软件工程/设计模式.md","filePath":"综合知识/软件工程/设计模式.md","lastUpdated":null}'),l={name:"综合知识/软件工程/设计模式.md"};function d(i,t,n,s,c,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 设计模式三分类（创建型/结构型/行为型）</li><li>[x] Bridge 桥接模式</li><li>[x] Proxy 代理模式</li><li>[x] Command 命令模式</li><li>[x] Strategy 策略模式</li><li>[x] Adapter 适配器模式</li><li>[x] Decorator 装饰器模式</li><li>[x] Abstract Factory 抽象工厂模式</li><li>[x] Wrapper Facade 包装器外观模式</li><li>[x] 模式辨析与选型</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、设计模式三分类-★" tabindex="-1">一、设计模式三分类 ★ <a class="header-anchor" href="#一、设计模式三分类-★" aria-label="Permalink to &quot;一、设计模式三分类 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：创建型管&quot;怎么造对象&quot;，结构型管&quot;类怎么组合&quot;，行为型管&quot;类怎么交互和分配职责&quot;。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">分类</th><th>作用</th><th>典型模式</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>创建型</strong></td><td>为类实例化新对象提供指南</td><td>Builder(构造器)、Prototype(原型)、Abstract Factory(抽象工厂)</td></tr><tr><td style="text-align:left;"><strong>结构型</strong></td><td>处理类或对象的组合，设计更大的结构</td><td>Adapter(适配器)、Facade(外观)、Proxy(代理)、Bridge(桥接)、Decorator(装饰器)</td></tr><tr><td style="text-align:left;"><strong>行为型</strong></td><td>描述类或对象的交互及职责分配</td><td>Command(命令)、Mediator(中介者)、State(状态)、Strategy(策略)、Observer(观察者)</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：Bridge 是结构型（不是行为型），Command 是行为型（不是创建型）。</p></blockquote><hr><h3 id="二、bridge-桥接模式-★" tabindex="-1">二、Bridge 桥接模式 ★ <a class="header-anchor" href="#二、bridge-桥接模式-★" aria-label="Permalink to &quot;二、Bridge 桥接模式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>将抽象部分与它的实现部分分离，使它们都可以独立变化。</strong>（Q1, Q2）</p></blockquote><ul><li>UML 角色：<strong>Abstraction</strong>（抽象类，如 Shape）←→ <strong>Implementor</strong>（实现接口，如 Drawing）</li><li><strong>与 Decorator 区分</strong>：Bridge 是分离抽象与实现（结构型），Decorator 是动态添加职责（结构型）</li><li><strong>与 Adapter 区分</strong>：Bridge 在设计阶段使用，Adapter 用于事后适配已有接口</li><li>适用：多种宣传产品形式（册子/文章/传单）+ 多种出版方式（纸质/CD/DVD/在线）</li></ul><hr><h3 id="三、proxy-代理模式-★" tabindex="-1">三、Proxy 代理模式 ★ <a class="header-anchor" href="#三、proxy-代理模式-★" aria-label="Permalink to &quot;三、Proxy 代理模式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>解决分布性问题最普遍的设计模式，CORBA 是其范例。</strong>（Q18）</p></blockquote><ul><li>为一个对象提供替身/占位符，以控制对它的访问</li><li>应用场景：远程代理（分布式系统）、虚拟代理（延迟加载）、保护代理（权限控制）</li><li>属于<strong>结构型</strong>模式</li></ul><hr><h3 id="四、command-命令模式-★" tabindex="-1">四、Command 命令模式 ★ <a class="header-anchor" href="#四、command-命令模式-★" aria-label="Permalink to &quot;四、Command 命令模式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>将一个请求封装为对象，从而可用不同请求对客户参数化、排队/记录日志、支持撤销。</strong>（Q44）</p></blockquote><ul><li>角色：Command（声明执行操作接口）、ConcreteCommand（具体命令，如 BuyStock/SellStock）、Invoker（调用者，如 Broker）</li><li><strong>股票交易 Broker</strong> 是典型场景：客户→Broker→Command→Receiver</li><li>属于<strong>行为型</strong>模式</li></ul><hr><h3 id="五、strategy-策略模式-★" tabindex="-1">五、Strategy 策略模式 ★ <a class="header-anchor" href="#五、strategy-策略模式-★" aria-label="Permalink to &quot;五、Strategy 策略模式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：定义一系列算法，将每个算法封装在具有公共接口的独立类中，使它们可以相互替换。</p></blockquote><ul><li>适用：促销系统（多种促销方式=多个策略类，从同一超类继承，标准接口方法计算折扣）</li><li>属于<strong>行为型</strong>模式</li></ul><hr><h3 id="六、adapter-适配器模式-★" tabindex="-1">六、Adapter 适配器模式 ★ <a class="header-anchor" href="#六、adapter-适配器模式-★" aria-label="Permalink to &quot;六、Adapter 适配器模式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>将一个接口转换为客户希望的另一个接口</strong>，使不兼容的接口能一起工作。</p></blockquote><ul><li>适用：集成不同供应商的税率计算类（每个供应商有不同调用方法），编写适配器子类映射调用</li><li>更换供应商 = 只需编写新的适配器子类</li><li>属于<strong>结构型</strong>模式</li></ul><hr><h3 id="七、decorator-装饰器模式-★" tabindex="-1">七、Decorator 装饰器模式 ★ <a class="header-anchor" href="#七、decorator-装饰器模式-★" aria-label="Permalink to &quot;七、Decorator 装饰器模式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>动态地给一个对象添加一些额外的职责</strong>，而无需修改此对象的结构。</p></blockquote><ul><li>属于<strong>结构型</strong>模式</li><li>与 Proxy 区分：Decorator 强调&quot;添加行为&quot;，Proxy 强调&quot;控制访问&quot;</li><li>与 Bridge 区分：Decorator 是动态扩展功能，Bridge 是分离抽象与实现</li></ul><hr><h3 id="八、abstract-factory-抽象工厂模式-★" tabindex="-1">八、Abstract Factory 抽象工厂模式 ★ <a class="header-anchor" href="#八、abstract-factory-抽象工厂模式-★" aria-label="Permalink to &quot;八、Abstract Factory 抽象工厂模式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：提供一个接口来创建一系列<strong>相关或相互依赖</strong>的对象，而无需指定它们具体的类。</p></blockquote><ul><li>属于<strong>创建型</strong>模式</li><li>与 Factory Method 区分：Abstract Factory 创建<strong>产品族</strong>，Factory Method 创建<strong>单个产品</strong></li></ul><hr><h3 id="九、wrapper-facade-包装器外观模式-★" tabindex="-1">九、Wrapper Facade 包装器外观模式 ★ <a class="header-anchor" href="#九、wrapper-facade-包装器外观模式-★" aria-label="Permalink to &quot;九、Wrapper Facade 包装器外观模式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：跨平台时封装不同 OS 的 API 差异，内部调用操作系统 API 函数，对外提供统一接口。</p></blockquote><ul><li>适用：TCP 并发服务端需同时支持 Linux/Solaris/Windows，不同 OS 的 Socket API 不同</li><li>程序调用 Wrapper Facade → 内部转发到具体 OS API</li></ul><hr><h3 id="十、模式辨析速查-★" tabindex="-1">十、模式辨析速查 ★ <a class="header-anchor" href="#十、模式辨析速查-★" aria-label="Permalink to &quot;十、模式辨析速查 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th style="text-align:center;">分类</th><th>一句话特征</th></tr></thead><tbody><tr><td>Bridge</td><td style="text-align:center;">结构型</td><td>分离抽象与实现，独立变化</td></tr><tr><td>Proxy</td><td style="text-align:center;">结构型</td><td>替身/占位，解决分布式问题</td></tr><tr><td>Adapter</td><td style="text-align:center;">结构型</td><td>转换接口，适配不兼容</td></tr><tr><td>Decorator</td><td style="text-align:center;">结构型</td><td>动态添加职责，不改变原对象</td></tr><tr><td>Facade</td><td style="text-align:center;">结构型</td><td>复杂子系统提供一个统一入口</td></tr><tr><td>Command</td><td style="text-align:center;">行为型</td><td>请求封装为对象，支持撤销</td></tr><tr><td>Strategy</td><td style="text-align:center;">行为型</td><td>算法族可互换</td></tr><tr><td>Observer</td><td style="text-align:center;">行为型</td><td>一对多依赖，状态变更通知</td></tr><tr><td>State</td><td style="text-align:center;">行为型</td><td>状态改变时改变行为</td></tr><tr><td>Abstract Factory</td><td style="text-align:center;">创建型</td><td>创建相关对象族</td></tr></tbody></table><blockquote><p>⚠️ 常见错误选项特征：把结构型模式说成行为型，反之亦然；把 Bridge 说成&quot;组合多个功能&quot;。</p></blockquote>',43)])])}const b=r(l,[["render",d]]);export{g as __pageData,b as default};
